// Filtrer les NOUVEAUX emails fournisseurs non lus (mémoire anti-doublon)
const seen = $getWorkflowStaticData('global');
seen.notified = seen.notified || {};
const data = $input.first().json;
let arr = Array.isArray(data) ? data : (data.emails || data.threads || data.result || []);
let flat = [];
for (const t of arr) {
  if (Array.isArray(t && t.messages)) flat.push(...t.messages);
  else flat.push(t);
}
// Les mails viennent déjà du dossier 'fournisseurs' (tri auto côté app).
// On filtre quand même pour la mémoire anti-doublon.
const SUPPLIERS = /./;
const out = [];
for (const e of flat) {
  const id = String(e.id || e.email_id || e.message_id || '');
  const sender = String(e.sender || e.from || '');
  const unread = (e.read === false || e.read === 0 || e.is_read === false);
  if (!id || seen.notified[id]) continue;
  if (!unread) continue;
  if (!SUPPLIERS.test(sender) && !SUPPLIERS.test(String(e.subject || ''))) continue;
  seen.notified[id] = true;
  out.push({
    json: {
      to: 'louiscyrano@gmail.com',
      subject: '\ud83d\udce7 Fournisseur : ' + (e.subject || '(sans objet)').slice(0, 90),
      text: 'Nouvel email fournisseur de ' + (sender || '?') + '\n\nSujet : ' + (e.subject || '') + '\n\n\u2192 R\u00e9ponds dans l\'app : https://agentic-inbox.louiscyrano.workers.dev'
    }
  });
}
// garder la map sous une taille raisonnable
const keys = Object.keys(seen.notified);
if (keys.length > 2000) { for (const k of keys.slice(0, 1000)) delete seen.notified[k]; }
return out;

// Relance si un email fournisseur n'a eu AUCUNE réponse de notre part depuis > 72h
const seen = $getWorkflowStaticData('global');
seen.followup = seen.followup || {};

function parseList(data) {
  let arr = Array.isArray(data) ? data : (data.emails || data.threads || data.result || []);
  let flat = [];
  for (const t of arr) {
    if (Array.isArray(t && t.messages)) flat.push(...t.messages);
    else flat.push(t);
  }
  return flat;
}
function get(obj, keys) { for (const k of keys) { if (obj && obj[k] !== undefined && obj[k] !== null) return obj[k]; } return undefined; }
function domainOf(addr) {
  const m = String(addr || '').match(/@([A-Za-z0-9.-]+)/);
  return m ? m[1].toLowerCase() : '';
}
function dateOf(e) {
  const v = get(e, ['date', 'received_at', 'created_at', 'receivedAt', 'sentAt']);
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d;
}

const inbox = parseList($('Lire la boîte').first().json);
const sent = parseList($input.first().json);
const SUPPLIERS = /prodigi|bigbuy|affliae|brickzone|imou|orderchimp|luzha|marketplace/i;
const now = Date.now();
const LIMIT = 72 * 3600 * 1000; // 3 jours

// index des envois : domaine destinataire -> date du dernier envoi
const lastSentTo = {};
for (const s of sent) {
  const d = dateOf(s);
  if (!d) continue;
  let tos = get(s, ['to', 'recipients']) || [];
  if (typeof tos === 'string') tos = [tos];
  for (const t of (Array.isArray(tos) ? tos : [])) {
    const addr = typeof t === 'string' ? t : (t.email || t.address || '');
    const dom = domainOf(addr);
    if (!dom) continue;
    if (!lastSentTo[dom] || d.getTime() > lastSentTo[dom]) lastSentTo[dom] = d.getTime();
  }
}

const out = [];
for (const e of inbox) {
  const sender = String(get(e, ['sender', 'from']) || '');
  const dom = domainOf(sender);
  const id = String(get(e, ['id', 'email_id', 'message_id']) || '');
  if (!id || seen.followup[id]) continue;
  if (!SUPPLIERS.test(sender) && !SUPPLIERS.test(String(e.subject || ''))) continue;
  const d = dateOf(e);
  if (!d) continue;
  const age = now - d.getTime();
  if (age < LIMIT) continue;                       // trop récent
  const replied = lastSentTo[dom] && lastSentTo[dom] > d.getTime();
  if (replied) continue;                            // déjà répondu après son email
  seen.followup[id] = true;
  const jours = Math.floor(age / 86400000);
  out.push({
    json: {
      to: 'louiscyrano@gmail.com',
      subject: '⏰ Relance à faire : ' + String(e.subject || '(sans objet)').slice(0, 90),
      text: 'Email de ' + sender + ' sans réponse depuis ' + jours + ' jours (reçu le ' + d.toLocaleDateString('fr-FR') + ').\n\n→ Réponds dans l\u2019app : https://agentic-inbox.louiscyrano.workers.dev\n(ou demande à ton agent IA : « rédige une relance pour ' + dom + ' »)'
    }
  });
}
// taille mémoire bornée
const keys = Object.keys(seen.followup);
if (keys.length > 2000) { for (const k of keys.slice(0, 1000)) delete seen.followup[k]; }
return out;

// Auto-classement : déplace les emails fournisseurs restés dans l'inbox vers 'fournisseurs'
const seen = $getWorkflowStaticData('global');
seen.moved = seen.moved || {};
const data = $input.first().json;
let arr = Array.isArray(data) ? data : (data.emails || data.threads || data.result || []);
let flat = [];
for (const t of arr) { if (Array.isArray(t && t.messages)) flat.push(...t.messages); else flat.push(t); }
const SUPPLIERS = /prodigi|bigbuy|affilae|brickzone|orderchimp|imou|awin/i;
const out = [];
for (const e of flat) {
  const id = String(e.id || '');
  const sender = String(e.sender || e.from || '');
  const folder = String(e.folder_id || e.folder || 'inbox');
  if (!id || folder === 'fournisseurs') continue;
  if (!SUPPLIERS.test(sender)) continue;
  if (seen.moved[id]) continue;
  out.push({ json: { emailId: id, sender } });
  seen.moved[id] = Date.now();
}
// purge mémoire > 7 jours
const week = 7*24*3600*1000;
for (const k of Object.keys(seen.moved)) if (Date.now() - seen.moved[k] > week) delete seen.moved[k];
return out;

